  if (est === 'proveedor_seleccionado') estado = !sel ? 'adjudicada (ganador no visible)' : (sel.rut_proveedor === CONF.rutJuncos ? 'ganada' : 'adjudicada a otro');
  else if (est === 'publicada') estado = 'abierta';
  const disp = num((d.presupuesto || {}).monto_disponible_clp) || p.json.monto_clp;
  const precio = sel ? num(sel.monto_total) : 0;
