const CONF = {"terminos": ["clima laboral", "encuesta", "estudio", "diagnostico", "capacitacion", "taller", "charla", "jornada", "liderazgo", "grupo focal", "consultoria", "comunicaciones", "pendon", "afiche", "lanyard"], "version": "2.0", "rutJuncos": "78.390.884-0", "ventana": 30, "minDet": 8, "minMotivo": 3, "minPrecio": 3, "diasEspera": 20};
const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const tiene = (t, lista) => lista.filter((w) => norm(t).includes(norm(w)));
const palabra = (t, lista) => lista.filter((w) => new RegExp('(^|[^a-z0-9])' + norm(w).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(s|es)?([^a-z0-9]|$)').test(norm(t)));
const ZONA = 'America/Santiago';
const ahora = DateTime.now().setZone(ZONA);
const num = (v) => { const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, '')); return isFinite(n) ? n : 0; };
// Revisión semanal: qué se detectó, qué se decidió, qué ganó y qué conviene ajustar.
const rows = $input.all().map((i) => i.json).filter((r) => r.codigo);
const fecha = (s) => DateTime.fromFormat(String(s || ''), 'dd-MM-yyyy HH:mm', { zone: ZONA });
const dentro = (r, dias) => { const d = fecha(r.revisada_el); return d.isValid && d >= ahora.minus({ days: dias }); };
const sem = rows.filter((r) => dentro(r, 7));
const ven = rows.filter((r) => dentro(r, CONF.ventana));
const dec = (r) => norm(r.decision);
const cotizada = (r) => /cotiz/.test(dec(r)) || r.juncos_cotizo === 'sí';
const descartada = (r) => /descart/.test(dec(r));
const conDec = sem.filter((r) => dec(r)).length;
const cotSem = sem.filter(cotizada).length;
const desSem = sem.filter(descartada).length;
const mediana = (a) => { if (!a.length) return null; const s = a.slice().sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const pct = (v) => v == null ? '—' : Math.round(v * 100) + '%';
// Motivos de descarte en la ventana
const motivos = {};
ven.filter(descartada).forEach((r) => { const m = String(r.motivo || 'sin motivo').trim().toLowerCase() || 'sin motivo'; motivos[m] = (motivos[m] || 0) + 1; });
// Rendimiento de cada término de búsqueda en la ventana
const term = {};
CONF.terminos.concat(['coquimbo']).forEach((t) => { term[t] = { det: 0, cot: 0 }; });
ven.forEach((r) => String(r.terminos || '').split(',').map((x) => x.trim()).filter(Boolean).forEach((t) => {
  term[t] = term[t] || { det: 0, cot: 0 }; term[t].det++; if (cotizada(r)) term[t].cot++; }));
// Precios ganadores por línea (todo el historial)
const conRes = rows.filter((r) => num(r.ratio_ganador) > 0);
const lineas = {};
conRes.forEach((r) => { const l = r.linea || 'consultoría'; (lineas[l] = lineas[l] || { ratios: [], ofertas: [] }).ratios.push(num(r.ratio_ganador)); if (num(r.ofertas_final)) lineas[l].ofertas.push(num(r.ofertas_final)); });
const ganadas = rows.filter((r) => r.estado_final === 'ganada').length;
const cotizadasTot = rows.filter(cotizada).length;
// Sugerencias: cada una dice qué cambiar en perfil_juncos.json y con qué evidencia
const sug = [];
if (sem.length && conDec / sem.length < 0.5) sug.push(`Solo ${conDec} de ${sem.length} Compras Ágiles de la semana tienen decisión. Marca la columna decision (cotizar o descartar) y el motivo: sin eso el ciclo no aprende.`);
Object.entries(term).forEach(([t, v]) => {
  if (v.det >= CONF.minDet && v.cot === 0) sug.push(`El término «${t}» trajo ${v.det} Compras Ágiles afines en ${CONF.ventana} días y ninguna se cotizó: evaluar quitarlo de compra_agil.n8n.terminos o afinarlo.`);
  if (ven.length >= 20 && v.det === 0 && t !== 'coquimbo') sug.push(`El término «${t}» no aportó ninguna Compra Ágil afín en ${CONF.ventana} días: evaluar reemplazarlo.`);
});
Object.entries(motivos).filter(([m, n]) => n >= CONF.minMotivo && m !== 'sin motivo').forEach(([m, n]) => sug.push(`«${m}» se repitió ${n} veces como motivo de descarte: evaluar una exclusión o una regla nueva en el perfil.`));
Object.entries(lineas).forEach(([l, v]) => { if (v.ratios.length >= CONF.minPrecio) sug.push(`En ${l}, el ganador ofertó en mediana el ${pct(mediana(v.ratios))} del monto disponible, con ${mediana(v.ofertas) || '—'} ofertas en mediana (${v.ratios.length} resultados): úsalo como referencia al fijar precios.`); });
if (cotizadasTot >= 5 && ganadas === 0) sug.push(`JUNCOS lleva ${cotizadasTot} Compras Ágiles cotizadas sin ganar: revisar precio frente a los ganadores (columna precio_ganador) y la descripción de las ofertas.`);
const fila = {
  semana_hasta: ahora.toFormat('dd-MM-yyyy'), version_flujo: CONF.version,
  detectadas: sem.length, con_decision: conDec, cotizadas: cotSem, descartadas: desSem,
  sin_decision: sem.length - conDec, precision: conDec ? Math.round(cotSem / conDec * 100) / 100 : '',
  resultados_conocidos: conRes.length, ganadas_juncos: ganadas,
  mediana_ratio_consultoria: lineas['consultoría'] ? mediana(lineas['consultoría'].ratios) : '',
  mediana_ratio_diseno: lineas['diseño'] ? mediana(lineas['diseño'].ratios) : '',
  sugerencias: sug.join(' | '),
};
const esc = (t) => String(t == null ? '' : t).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const filaT = (a, b) => `<tr><td>${esc(a)}</td><td style="text-align:right">${esc(b)}</td></tr>`;
const tablaT = Object.entries(term).sort((a, b) => b[1].det - a[1].det).map(([t, v]) => `<tr><td>${esc(t)}</td><td style="text-align:right">${v.det}</td><td style="text-align:right">${v.cot}</td></tr>`).join('');
const asunto = `JUNCOS · Mejora semanal ${fila.semana_hasta}: ${sem.length} detectadas, ${cotSem} cotizadas, ${sug.length} sugerencias`;
const html = `<p>Revisión semanal del flujo n8n v${CONF.version}.</p>`
  + '<h3>La semana</h3><table border="1" cellpadding="6" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">'
  + filaT('Detectadas', sem.length) + filaT('Con decisión', conDec) + filaT('Cotizadas', cotSem) + filaT('Descartadas', desSem)
  + filaT('Precisión (cotizadas / con decisión)', fila.precision === '' ? '—' : pct(fila.precision))
  + filaT('Resultados conocidos (historial)', conRes.length) + filaT('Ganadas por JUNCOS', ganadas) + '</table>'
  + `<h3>Sugerencias (${sug.length})</h3>` + (sug.length ? '<ol>' + sug.map((x) => `<li>${esc(x)}</li>`).join('') + '</ol>' : '<p>Ninguna esta semana.</p>')
  + `<h3>Términos de búsqueda (${CONF.ventana} días)</h3><table border="1" cellpadding="6" style="border-collapse:collapse;font-family:sans-serif;font-size:13px"><tr><th>Término</th><th>Afines</th><th>Cotizadas</th></tr>` + tablaT + '</table>'
  + '<p><small>Las sugerencias no se aplican solas: Claude las revisa contigo y, si las apruebas, actualiza perfil_juncos.json, sube la versión y regenera el flujo.</small></p>';
const texto = `MEJORA SEMANAL. Flujo n8n v${CONF.version}, semana hasta ${fila.semana_hasta}. `
  + `Detectadas ${sem.length}, con decisión ${conDec}, cotizadas ${cotSem}, descartadas ${desSem}, resultados conocidos ${conRes.length}, ganadas ${ganadas}. `
  + `Motivos de descarte: ${JSON.stringify(motivos)}. Términos: ${JSON.stringify(term)}. Sugerencias: ${sug.join(' | ') || 'ninguna'}.`;
return [{ json: { fila, asunto, html, texto } }];
